// Playing strength for beginners and casual players.
//
// Even Stockfish's weakest built-in setting beats most beginners, and its
// mistakes look random. Instead, each level asks the engine for its top
// candidate moves at a shallow depth and picks among them like a person of
// that strength: usually a sensible move, sometimes a second-best one, and now
// and then a real mistake (a piece left hanging, a missed tactic). The engine
// still judges every candidate, so even a weak level never plays nonsense.
// Pure functions, unit tested; calibrated by engine-vs-engine matches
// (npm run calibrate).
import type { Score, SearchInfo } from "./uci.js";

export interface Level {
  id: number;
  name: string;
  /** One line for the level picker. */
  blurb: string;
  /** Search depth for the candidate moves: how far ahead this level "sees". */
  depth: number;
  /** How many candidate moves the engine reports. */
  multiPv: number;
  /** Largest loss (centipawns) for an ordinary move choice. */
  maxLoss: number;
  /** How readily a worse candidate is chosen: higher is more erratic. */
  temperature: number;
  /** Chance per move of a real mistake. */
  slipChance: number;
  /** Largest loss (centipawns) such a mistake may cost. */
  slipMaxLoss: number;
}

