export function levelById(id: number): Level {
  return LEVELS.find((l) => l.id === id) ?? LEVELS[0]!;
}

const MATE = 100_000;
/** Each move a mate takes longer counts like this many centipawns. */
const MATE_STEP = 100;
/**
 * Losses above this are capped: missing a mate counts like losing about a
 * queen. Only a level whose slipMaxLoss reaches the cap (level 1) can ever
 * walk into or miss a mate it saw; every other level always takes a mate.
 */
export const LOSS_CAP = 1000;

/**
 * A score as centipawns for the side to move, so that bigger is better for
 * whoever is choosing. Scores arrive from White's point of view. A forced
 * mate counts as far more than any material, and a quicker mate as clearly
 * better, so a strong level plays mate in 1 rather than mate in 3.
 */
export function moverCp(score: Score | undefined, side: "w" | "b"): number {
  if (!score) return 0;
  if (score.mate === 0) return -MATE; // the side to move is already checkmated
  const sign = side === "w" ? 1 : -1;
  if (score.mate !== undefined) {
    const m = score.mate;
    const white = m > 0 ? MATE - MATE_STEP * m : -MATE - MATE_STEP * m;
    return sign * white;
  }
  return sign * (score.cp ?? 0);
}

export interface Candidate {
  move: string;
  /** Centipawns lost compared with the best candidate (0 for the best). */
  loss: number;
}

export function candidates(lines: SearchInfo[], side: "w" | "b"): Candidate[] {
  const scored = lines
    .filter((l) => l.pv[0])
    .map((l) => ({ move: l.pv[0]!, cp: moverCp(l.score, side) }));
  if (!scored.length) return [];
  const best = Math.max(...scored.map((c) => c.cp));
  return scored.map((c) => ({ move: c.move, loss: Math.min(best - c.cp, LOSS_CAP) }));
}

/** Chooses a move for `level` from the engine's candidate lines. */
export function pickMove(
  lines: SearchInfo[],
  side: "w" | "b",
  level: Level,
  rng: () => number = Math.random,
): string | null {
  const cands = candidates(lines, side);
  if (!cands.length) return null;

  if (level.slipChance > 0 && rng() < level.slipChance) {
    const mistakes = cands.filter((c) => c.loss > 0 && c.loss <= level.slipMaxLoss);
    if (mistakes.length) return mistakes[Math.floor(rng() * mistakes.length)]!.move;
  }

  const pool = cands.filter((c) => c.loss <= level.maxLoss);
  const weights = pool.map((c) => Math.exp(-c.loss / Math.max(level.temperature, 1)));
  const total = weights.reduce((a, b) => a + b, 0);
  let r = rng() * total;
  for (let i = 0; i < pool.length; i++) {
    r -= weights[i]!;
    if (r <= 0) return pool[i]!.move;
  }
  return pool[pool.length - 1]!.move;
}

/** Small seeded random generator (mulberry32), for repeatable tests and matches. */
export function seededRandom(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
